import {IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent,IonButton} from "@ionic/react";
import {useState} from "react";
export default function App(){const [count,setCount]=useState(0);return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><IonButton onClick={()=>setCount(count+1)}>Read one</IonButton><p>Books: {count}</p></IonContent></IonPage></IonApp>;}

import {IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent,IonInput} from "@ionic/react";
import {useState} from "react";
export default function App(){const [name,setName]=useState("");return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><IonInput label="Your name" labelPlacement="stacked" value={name} onIonInput={event=>setName(event.detail.value ?? "")}/><p>Hello, {name}</p></IonContent></IonPage></IonApp>;}

import {IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent,IonSelect,IonSelectOption} from "@ionic/react";
import {useState} from "react";
export default function App(){const [kind,setKind]=useState("story");return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><IonSelect label="Book type" value={kind} onIonChange={event=>setKind(event.detail.value)}><IonSelectOption value="story">Story</IonSelectOption><IonSelectOption value="science">Science</IonSelectOption></IonSelect><p>Type: {kind}</p></IonContent></IonPage></IonApp>;}

import {IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent,IonCheckbox} from "@ionic/react";
import {useState} from "react";
export default function App(){const [ready,setReady]=useState(false);return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><IonCheckbox checked={ready} onIonChange={event=>setReady(event.detail.checked)}>Ready to read</IonCheckbox><p>{ready?"Ready":"Not ready yet"}</p></IonContent></IonPage></IonApp>;}

import {IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent,IonButton,IonToast} from "@ionic/react";
import {useState} from "react";
export default function App(){const [open,setOpen]=useState(false);return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><IonButton onClick={()=>setOpen(true)}>Mark practice done</IonButton><IonToast isOpen={open} message="Practice marked as done" duration={2000} onDidDismiss={()=>setOpen(false)}/></IonContent></IonPage></IonApp>;}

import {IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent,IonButton,IonModal} from "@ionic/react";
import {useState} from "react";
export default function App(){const [open,setOpen]=useState(false);return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><IonButton onClick={()=>setOpen(true)}>Book help</IonButton><IonModal isOpen={open} onDidDismiss={()=>setOpen(false)}><IonHeader><IonToolbar><IonTitle>Book help</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><p>Choose a short story first.</p><IonButton onClick={()=>setOpen(false)}>Close help</IonButton></IonContent></IonModal></IonContent></IonPage></IonApp>;}
